-- Module 7: math-algebra (30 sections, 4997 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:math-algebra')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'math-algebra', 'math-algebra', 'Math: Algebra', 'Linear equations, linear functions, two-variable equations, systems and inequalities on the digital SAT: what is tested, nine worked examples, the traps that cost points, when to use Desmos, and a ten-question drill with explanations.', 'published', 'public', 'en', 7, 'SAT Math Algebra Guide: Linear Equations, Systems and Inequalities | SAT Playbook', 'A complete guide to the Algebra domain of the digital SAT Math section, with original worked examples, common traps, Desmos decision rules, student-produced response tips and a practice drill.', array['SAT', 'SAT Math', 'SAT Algebra', 'linear equations', 'systems of equations', 'linear inequalities', 'Digital SAT', 'Bluebook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"math-algebra","module_group":"domain_math","migration_group":"math","hero_kicker":"Module 7","word_count":4997,"section_count":30,"reading_minutes":25,"estimated_reading_minutes":25,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Algebra question bank","url":"https://practice.sat.schood.online/bank?section_type=math&domain=algebra"},{"label":"Hard Algebra questions","url":"https://practice.sat.schood.online/bank?section_type=math&domain=algebra&difficulty=hard"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"},{"label":"Full SAT simulator","url":"https://sat.schood.online"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:math-algebra:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why Algebra Matters', '{"markdown":"Algebra is one of the two largest domains on the SAT Math section. College Board''s specifications put it at about **35% of Math questions, roughly 13 to 15 of the 44**, and it appears in both modules. Advanced Math carries the same weight, so together these two domains make up about 70% of the section.\n\nAlgebra on the SAT means **linear** algebra: equations, functions, inequalities and systems whose graphs are straight lines or regions bounded by straight lines. Nothing here requires a formula you have never seen. What separates scores is not knowledge but precision: solving for the right quantity, reading what a slope means in a story, recognising when two lines never meet, and entering a student-produced response in a form the scoring system accepts.\n\nAlgebra habits also carry over: isolating a variable cleanly, translating words into equations and checking by substitution are what Advanced Math, data and geometry questions rely on. Fast, accurate Algebra leaves more time for the hardest questions at the end of each module."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'Key Outcomes', '{"items":["Solve any linear equation in one variable, including ones with fractions, decimals and distribution.","Recognise when a linear equation has exactly one, no or infinitely many solutions.","Build a linear function from a table, a graph, two points or a story, and interpret its slope and intercept.","Write and use linear equations in two variables, including parallel and perpendicular lines.","Solve systems of two linear equations by substitution, elimination or Desmos, and classify the number of solutions.","Write, solve and graph linear inequalities in one or two variables.","Answer the quantity the question asks for, not just the variable you solved for.","Enter student-produced responses that follow the official Bluebook rules."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where Algebra Sits in the Math Section', '{"markdown":"The digital SAT Math section has **two modules of 22 questions each, with 35 minutes per module**. Two questions in each module are unscored pretest questions that look exactly like the others, so treat every question as if it counts. Questions from all four Math domains appear in each module, arranged from easiest to hardest.\n\n| Fact | What it means for Algebra |\n|---|---|\n| About 35% of Math, 13–15 questions | Expect roughly 6 to 8 Algebra questions per module. |\n| Two modules, 22 questions, 35 minutes each | About 95 seconds per question on average, but early questions should take far less. |\n| Easiest to hardest within each module | The first Algebra questions are quick wins; the last ones are often systems or parameters. |\n| About 30% of Math questions are in context | Many Algebra questions are short stories about costs, rates or quantities. |\n| Calculator allowed on every question | The built-in Desmos graphing calculator is always available, and you may bring an approved handheld. |\n\nThe skills College Board lists for this domain are: linear equations in one variable, linear functions, linear equations in two variables, systems of two linear equations in two variables, and linear inequalities in one or two variables. The rest of this module takes them one at a time."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'How Algebra Questions Look on Screen', '{"markdown":"Most Math questions are four-option multiple choice, and about a quarter are **student-produced responses (SPR)**, where you type your own answer into a box. Algebra produces many SPR questions because linear equations usually have one clean numerical answer.\n\nAlgebra questions arrive in three typical shapes:\n\n- **Pure equations.** \"If 7x − 4 = 3x + 20, what is the value of x?\" These reward clean manipulation.\n- **Short contexts.** A gym fee, a draining tank, a phone plan. You translate the story into an equation, then answer a question about it, often about what a number in the equation means.\n- **Structure questions.** \"For what value of k does the system have no solution?\" Here you reason about coefficients instead of solving for x.\n\nPure equations fail on arithmetic slips, contexts on misreading which quantity is which, and structure questions when a student tries to solve numerically something that is really about parallel lines."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Skill 1: Linear Equations in One Variable', '{"markdown":"A linear equation in one variable has the variable to the first power only, such as 5(x − 2) = 3x + 8. The goal is to isolate x by doing the same operation to both sides.\n\n### The reliable order of operations for solving\n\n1. **Clear fractions** by multiplying both sides by the least common denominator.\n2. **Distribute** across every parenthesis, paying attention to negative signs.\n3. **Collect** variable terms on one side and constants on the other.\n4. **Divide** by the coefficient of the variable.\n5. **Check** by substituting back, especially on SPR questions where there is no answer choice to confirm you.\n\n### How many solutions?\n\nAfter simplifying, every linear equation ends in one of three forms:\n\n- **ax = b with a ≠ 0** → exactly one solution, x = b/a.\n- **0 = b with b ≠ 0** (for example 0 = 7) → no solution. The variable terms cancelled and left a false statement.\n- **0 = 0** → infinitely many solutions. Both sides were the same expression all along.\n\nThe SAT likes to ask the reverse question: what constant makes an equation have no solution or infinitely many? The answer comes from matching coefficients, which the second worked example shows."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Worked Example 1: Solve for the Quantity Asked', '{"markdown":"**Question (multiple choice).** If 4(x − 3) + 2 = 2x + 10, what is the value of x − 3?\n\nA) −3\nB) 5/2\nC) 7\nD) 10\n\n**Solution.** Distribute: 4x − 12 + 2 = 2x + 10, so 4x − 10 = 2x + 10. Subtract 2x and add 10 to both sides: 2x = 20, so x = 10. The question asks for x − 3, which is **7**. The answer is **C**.\n\n**Why the other choices are tempting.**\n\n- **D (10)** is the value of x. It is the single most common wrong answer on questions like this: correct algebra, wrong final step.\n- **B (5/2)** comes from distributing the 4 only to the x: 4x − 3 + 2 = 2x + 10 gives x = 11/2, and 11/2 − 3 = 5/2.\n- **A (−3)** comes from a sign slip when moving −10, which turns 2x = 20 into 2x = 0.\n\n**Desmos path.** Type `4(x-3)+2=2x+10`. Desmos draws a vertical line at x = 10. You still have to subtract 3 yourself, which is exactly why reading the question twice matters."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Worked Example 2: Infinitely Many Solutions', '{"markdown":"**Question (student-produced response).** In the equation 3(2x + k) = 6x − 12, k is a constant. If the equation has infinitely many solutions, what is the value of k?\n\n**Solution.** Distribute: 6x + 3k = 6x − 12. The x terms already match (6x on both sides), so the equation is true for every x only if the constants also match: 3k = −12, so **k = −4**. Enter `-4`.\n\n**What to notice.**\n\n- If k were any other number, the x terms would cancel and leave a false statement such as 0 = 9, meaning no solution. The SAT can ask either version from the same setup.\n- A student who forgets to distribute the 3 writes 6x + k = 6x − 12 and enters −12. On SPR there is no answer list to warn you, so distribution errors are especially costly here.\n\n**Decision rule.** When a question says \"infinitely many solutions,\" set the x coefficients equal and the constants equal. When it says \"no solution,\" set the x coefficients equal and make the constants different."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Skill 2: Linear Functions', '{"markdown":"A linear function has the form f(x) = mx + b. The **slope m** is the constant rate of change: how much f(x) changes when x increases by 1. The **intercept b** is the value of f(0), the starting amount in most contexts.\n\n### Finding the function\n\n- **From two points** (x₁, y₁) and (x₂, y₂): m = (y₂ − y₁)/(x₂ − x₁), then substitute one point to find b.\n- **From a table**: check that equal steps in x produce equal steps in f(x). The ratio of those steps is the slope.\n- **From a story**: the rate (per hour, per item, per month) is the slope; the fixed amount (sign-up fee, starting balance, initial height) is the intercept.\n\n### Interpreting a linear model\n\nThe SAT often gives a model such as C(m) = 25m + 40 and asks what 25 or 40 means. Answer in the language of the story, with units: \"the cost increases by $25 for each additional month\" and \"the cost is $40 before any months have passed.\" If the slope is negative, it describes a decrease per unit: a model like V(t) = 900 − 60t loses 60 units each time t increases by 1.\n\n### Function notation\n\nf(3) means \"the output when the input is 3.\" If a question says f(a) = 11, you are solving mx + b = 11 for x = a. Keep inputs and outputs straight; mixing them up is a frequent mid-module error."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Worked Example 3: A Draining Tank', '{"markdown":"**Question (student-produced response).** A tank holds 240 liters of water. Water drains at a constant rate, and after 6 minutes the tank holds 198 liters. If the water keeps draining at this rate, how many minutes after draining began will the tank be empty?\n\n**Solution.** The tank lost 240 − 198 = 42 liters in 6 minutes, so the rate is 42 ÷ 6 = 7 liters per minute. The amount left is W(t) = 240 − 7t. Set W(t) = 0: 7t = 240, so t = 240/7 ≈ 34.2857 minutes.\n\n**Entering the answer.** The official Bluebook rules allow up to 5 characters for a positive answer. You may enter the fraction `240/7` (5 characters), or a decimal that fills the space: `34.28` or `34.29`. An entry such as 34.3 is less precise than the space allows and risks being marked wrong. Never type units.\n\n**Trap to avoid.** Some students compute 198 ÷ 7 ≈ 28.3, the time remaining after the 6-minute mark, and forget to add the first 6 minutes. Always ask what \"time zero\" is in the question.\n\n**Desmos path.** Enter `y=240-7x`, then click where the line crosses the x-axis. Desmos shows the point (34.286, 0). Use the exact fraction or fill all five characters when entering."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Skill 3: Linear Equations in Two Variables', '{"markdown":"An equation such as 12x + 9y = 540 describes all the combinations of x and y that make it true. Its graph is a line. You will meet it in two forms:\n\n| Form | Looks like | Best for |\n|---|---|---|\n| Slope-intercept | y = mx + b | Reading slope and y-intercept directly, graphing |\n| Standard | Ax + By = C | Budget and mixture stories, finding intercepts quickly |\n| Point-slope | y − y₁ = m(x − x₁) | Writing a line from one point and a slope |\n\n### Facts worth memorising\n\n- The slope of Ax + By = C is −A/B.\n- **Parallel lines** have equal slopes and different intercepts.\n- **Perpendicular lines** have slopes that multiply to −1; the new slope is the negative reciprocal (for example 2 becomes −1/2).\n- The x-intercept is found by setting y = 0; the y-intercept by setting x = 0.\n\n### Context reading\n\nIn 12x + 9y = 540, if x counts adult tickets at $12 and y counts student tickets at $9, then 540 is the total budget in dollars. The x-intercept, 45, is the number of adult tickets you could buy if you bought no student tickets."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Worked Example 4: A Ticket Budget', '{"markdown":"**Question (multiple choice).** A club spends exactly $540 on adult tickets that cost $12 each and student tickets that cost $9 each. The equation 12x + 9y = 540 represents this, where x is the number of adult tickets and y is the number of student tickets. If the club buys 18 adult tickets, how many student tickets does it buy?\n\nA) 24\nB) 36\nC) 42\nD) 58\n\n**Solution.** Substitute x = 18: 12(18) = 216, so 9y = 540 − 216 = 324 and y = 36. The answer is **B**.\n\n**Why the other choices are tempting.**\n\n- **C (42)** comes from 540/9 − 18: subtracting the number of tickets instead of the cost of those tickets.\n- **D (58)** comes from (540 − 18)/9: subtracting 18 dollars instead of 18 tickets'' worth of dollars.\n- **A (24)** comes from 216/9: dividing the adult spending, not the money left over, by the student price.\n\n**Lesson.** In mixed-unit stories, write units next to each number: 18 tickets, $216, $324. Errors appear exactly where units are mixed."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Worked Example 5: A Perpendicular Line', '{"markdown":"**Question (student-produced response).** Line j passes through the points (−2, 5) and (4, −7). Line k is perpendicular to line j and passes through the point (6, 1). What is the y-coordinate of the y-intercept of line k?\n\n**Solution.** Slope of j: (−7 − 5)/(4 − (−2)) = −12/6 = −2. A perpendicular slope is the negative reciprocal, 1/2. For line k, y = (1/2)x + b. Substitute (6, 1): 1 = 3 + b, so **b = −2**. Enter `-2`.\n\n**Common wrong answers.**\n\n- Using the same slope −2 is the parallel-line mistake. Using slope 2 (just flipping the sign) gives 1 = 12 + b, so b = −11.\n- Using −1/2 (reciprocal without changing sign) gives 1 = −3 + b, so b = 4.\n\n**Desmos check.** Type `y=(1/2)(x-6)+1` and read the y-intercept (0, −2). You can also graph line j as `y=-2(x+2)+5` and confirm the two lines meet at a right angle."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Skill 4: Systems of Two Linear Equations', '{"markdown":"A system asks for the point that satisfies two equations at once. Graphically, it is where two lines intersect.\n\n### Three methods\n\n- **Substitution**: best when one equation already isolates a variable, such as y = 3x − 1 or x = y + 2.\n- **Elimination**: best when coefficients line up, such as 2x + 3y = 13 and 2x − y = 1; subtract to remove x.\n- **Desmos**: type both equations, click the intersection. Fast, and excellent for checking.\n\n### Number of solutions\n\n| Situation | Slopes | Intercepts | Solutions |\n|---|---|---|---|\n| Lines cross | Different | Any | Exactly one |\n| Parallel lines | Equal | Different | None |\n| Same line | Equal | Equal | Infinitely many |\n\nFor equations in standard form, a₁x + b₁y = c₁ and a₂x + b₂y = c₂, compare ratios. If a₁/a₂ = b₁/b₂ but that ratio is not equal to c₁/c₂, there is no solution. If all three ratios are equal, there are infinitely many.\n\n### Asking for a combination\n\nThe SAT often asks for x + y, x − y or 2x + 3y rather than x alone. Sometimes you can add or subtract the equations to produce that combination directly without solving for each variable. Look for that shortcut before grinding through substitution."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Worked Example 6: A Standard System', '{"markdown":"**Question (multiple choice).** If 3x + 2y = 16 and x − y = 2, what is the value of x + y?\n\nA) 2\nB) 4\nC) 6\nD) 8\n\n**Solution.** From the second equation, x = y + 2. Substitute: 3(y + 2) + 2y = 16, so 5y + 6 = 16 and y = 2. Then x = 4, and x + y = **6**. The answer is **C**.\n\n**Why the other choices are tempting.** B is x alone, A is y alone, and D is the product xy. All three are numbers a student naturally calculates on the way, which is exactly why they appear as choices.\n\n**Desmos path.** Type `3x+2y=16` and `x-y=2` on separate lines. Click the intersection point to see (4, 2). Add the coordinates yourself. This takes about 20 seconds and is a strong check even when you solved by hand."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Worked Example 7: A System With No Solution', '{"markdown":"**Question (student-produced response).** In the system kx + 6y = 9 and 2x + 3y = 5, k is a constant. For what value of k does the system have no solution?\n\n**Solution.** No solution means the lines are parallel and distinct. The y coefficients are in the ratio 6 : 3 = 2, so the x coefficients must be in the same ratio: k/2 = 2, so **k = 4**. Check that the lines are distinct, not identical: doubling the second equation gives 4x + 6y = 10, while the first is 4x + 6y = 9. Same left side, different right side, so no solution. Enter `4`.\n\n**Follow-up version.** If the first equation were 4x + 6y = c, the system would have infinitely many solutions only when c = 10.\n\n**Desmos path.** Add a slider: type `kx+6y=9` and `2x+3y=5`, accept the slider for k, and drag it until the lines become parallel. The slider lands on k = 4. This is slower than the ratio method but builds intuition."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Skill 5: Linear Inequalities', '{"markdown":"Linear inequalities work like equations with one extra rule: **multiplying or dividing both sides by a negative number reverses the inequality sign.** For example, −3x < 9 becomes x > −3.\n\n### One-variable inequalities in context\n\nWords to translate:\n\n- \"At most,\" \"no more than,\" \"maximum\" → ≤\n- \"At least,\" \"no fewer than,\" \"minimum\" → ≥\n- \"More than,\" \"exceeds\" → >\n- \"Fewer than,\" \"less than\" → <\n\nWhen the variable counts whole objects (boxes, tickets, people), the answer must be a whole number, and you usually round **down** for a maximum and **up** for a minimum.\n\n### Two-variable inequalities\n\nAn inequality such as y > 2x − 3 describes a region of the plane. The boundary line is dashed for > or < and solid for ≥ or ≤. A point is a solution if its coordinates make the inequality true. For a system of inequalities, the solution set is the overlap of the regions. The fastest reliable method on test day is usually to **substitute each answer choice** into every inequality."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked Example 8: The Delivery Van', '{"markdown":"**Question (student-produced response).** A delivery van can carry at most 1,200 kilograms, including the driver. The driver weighs 80 kilograms and each box weighs 22 kilograms. What is the maximum number of boxes the van can carry?\n\n**Solution.** Write 80 + 22b ≤ 1,200. Then 22b ≤ 1,120, so b ≤ 50.909... Because b counts boxes, the maximum is **50**. Check: 80 + 22(50) = 1,180 kg, which is allowed; 80 + 22(51) = 1,202 kg, which is over the limit. Enter `50`.\n\n**Traps.** Rounding 50.9 up to 51 breaks the limit. Forgetting the driver gives 1,200/22 ≈ 54.5 and an answer of 54. Typing a comma (1,120) anywhere in an SPR box is not allowed; type digits only."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Worked Example 9: A System of Inequalities', '{"markdown":"**Question (multiple choice).** Which point (x, y) is a solution to the system y > 2x − 3 and y ≤ −x + 6?\n\nA) (4, 3)\nB) (0, −4)\nC) (2, 5)\nD) (1, 0)\n\n**Solution.** Test each point in both inequalities.\n\n- (4, 3): 3 > 5 is false. Rejected.\n- (0, −4): −4 > −3 is false. Rejected.\n- (2, 5): 5 > 1 is true, but 5 ≤ 4 is false. Rejected.\n- (1, 0): 0 > −1 is true and 0 ≤ 5 is true. **Accepted.**\n\nThe answer is **D**. Choice C is the classic trap: it satisfies one inequality, and students who check only the first one stop there.\n\n**Desmos path.** Type `y>2x-3` and `y<=-x+6`. Desmos shades both regions. Type the four points as `(4,3)`, `(0,-4)`, `(2,5)`, `(1,0)` and see which one sits in the darker overlap. Points on a dashed boundary are not solutions."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Common Traps in Algebra', '{"markdown":"### Arithmetic and sign traps\n\n- **Distributing a negative**: −2(x − 5) is −2x + 10, not −2x − 10.\n- **Moving terms across the equals sign** without changing the sign.\n- **Forgetting to flip** an inequality after dividing by a negative.\n\n### Reading traps\n\n- **Solving for the wrong quantity**: the question asks for 2x, x − 3 or x + y, and you stop at x.\n- **Mixing units**: tickets versus dollars, minutes versus hours, kilograms versus boxes.\n- **Confusing slope and intercept** in context: \"the starting fee\" is the intercept, \"per month\" is the slope.\n\n### Structure traps\n\n- **\"No solution\" versus \"infinitely many\"**: both need equal slopes; they differ only in whether the intercepts (or constants) match.\n- **Assuming one solution**: if the variables cancel while you solve, stop and decide whether the leftover statement is true or false.\n- **Perpendicular slope**: take the reciprocal **and** change the sign.\n\n### SPR traps\n\n- Entering a rounded decimal with fewer digits than the box allows.\n- Entering a mixed number such as 3 1/2, which is read incorrectly. Use 7/2 or 3.5.\n- Typing symbols such as %, $ or commas."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'callout', 'Read the Last Line Twice', '{"label":"The quantity you solve for is not always the answer","body":"On the digital SAT, many wrong answer choices are numbers you really did compute on the way to the answer. Before you click or type, reread the final line of the question and confirm whether it asks for x, a combination like x plus y, a constant like k, or a meaning in context. This ten-second habit protects more Algebra points than any trick."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Decision Rules: By Hand, Desmos or Backsolve', '{"markdown":"Use these rules to choose a method quickly instead of deciding afresh on every question.\n\n### Solve by hand when\n\n- The equation is one or two steps, such as 5x − 7 = 3x + 9. Typing it would take longer than solving it.\n- The question is about structure (no solution, infinitely many, a parameter k). Coefficient reasoning is faster and more reliable.\n- The question asks what a number means in context. No calculator can answer that.\n\n### Use Desmos when\n\n- A system has messy coefficients or decimals. Type both equations and click the intersection.\n- You need an intercept or the point where a model reaches a value, such as when a tank is empty.\n- You want to verify a hand solution on a hard question late in the module.\n- You are testing which point satisfies a system of inequalities.\n\n### Backsolve (try the answer choices) when\n\n- The choices are numbers and the equation is awkward to rearrange.\n- Start with a middle value. If it is too big or too small, you often know which choice to test next.\n\n### Choose numbers when\n\n- The question and choices are in terms of variables, such as \"which expression represents...\" Pick simple values (for example x = 2), compute the target, and test each choice.\n\nThe full set of Desmos techniques is in the [Desmos and calculator strategy module](https://playbook.sat.schood.online/desmos-and-calculator-strategy)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Entering Student-Produced Responses', '{"markdown":"Algebra produces many SPR questions. The official Bluebook directions set these rules:\n\n- You can enter **up to 5 characters for a positive answer** and **up to 6 for a negative answer**, including the minus sign.\n- **Fractions or decimals** are both fine. If a fraction does not fit, enter its decimal.\n- If a decimal is too long, **truncate or round at the fourth digit**, filling the space. For 2/3, entries such as `2/3`, `.6666`, `.6667`, `0.666` and `0.667` work; `0.66` and `.67` do not.\n- **Mixed numbers** must be entered as improper fractions or decimals: 3½ as `7/2` or `3.5`.\n- **No symbols**: no %, $ or commas.\n- If more than one answer is correct, **enter only one**.\n\nBluebook shows a preview of what you typed. Glance at it before moving on: a missing minus sign is the most common SPR slip."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Timing by Question Position', '{"markdown":"Because each module runs from easiest to hardest, the position of a question tells you how much time it deserves.\n\n| Position in module | Typical Algebra content | Target time |\n|---|---|---|\n| Questions 1–7 | One-step equations, reading slope or intercept | 30–60 seconds |\n| Questions 8–15 | Two-step contexts, systems, inequalities in words | 60–90 seconds |\n| Questions 16–22 | Parameters (k), no-solution systems, dense contexts | 90–150 seconds |\n\n### Pacing habits\n\n- Early Algebra questions are where you bank time. Do them carefully but without overthinking.\n- If a mid-module question is taking more than two minutes, mark it for review, choose your best answer and move on. You can return before the module timer ends.\n- Never leave a question blank. College Board advises that guessing is generally better than leaving an answer empty, especially after eliminating choices.\n\nMore on how module 1 affects module 2 is in [Pacing and adaptive modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Algebra Drill: Ten Questions', '{"markdown":"Try these under light time pressure: about 12 minutes for all ten. Answers and explanations follow in the next section.\n\n**1.** If 5x − 7 = 3x + 9, what is the value of 2x?\nA) 1  B) 8  C) 16  D) 32\n\n**2.** (SPR) If (2/3)x + 4 = 10, what is the value of x?\n\n**3.** (SPR) A linear function f has f(0) = −3 and f(2) = 5. What is the value of f(6)?\n\n**4.** A gym charges a $40 sign-up fee plus $25 per month. Which equation gives the total cost C, in dollars, for m months?\nA) C = 40m + 25  B) C = 25m + 40  C) C = 65m  D) C = 25(m + 40)\n\n**5.** (SPR) If y = 3x − 1 and 2x + y = 14, what is the value of y?\n\n**6.** Which system of equations has no solution?\nA) y = 2x + 1 and y = −2x + 1\nB) y = 2x + 1 and 2y = 4x + 2\nC) y = 2x + 1 and y = 2x − 5\nD) y = x and y = 2x\n\n**7.** (SPR) The system 3x − 2y = 12 and ax + 4y = −24 has infinitely many solutions. What is the value of a?\n\n**8.** (SPR) What is the smallest integer x that satisfies −3(x − 2) < 15?\n\n**9.** The function f(t) = 1,500 − 45t gives the number of pages a student has left to read t days after starting a reading list. What is the best interpretation of 45?\nA) The total number of pages on the list\nB) The number of days needed to finish\nC) The number of pages the student reads each day\nD) The number of pages left after one day\n\n**10.** (SPR) In the equation a(x + 3) − 2x = 4x + 18, a is a constant. If the equation has infinitely many solutions, what is the value of a?"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"**1. C (16).** Subtract 3x and add 7: 2x = 16. The question asks for 2x, so stop there. B (8) is x; D (32) doubles again.\n\n**2. 9.** Subtract 4: (2/3)x = 6. Multiply by 3/2: x = 9.\n\n**3. 21.** The slope is (5 − (−3))/(2 − 0) = 4, so f(x) = 4x − 3 and f(6) = 24 − 3 = 21.\n\n**4. B.** The fixed fee is the intercept (40) and the monthly charge is the slope (25). A swaps them; C pretends both repeat monthly; D multiplies the fee by 25.\n\n**5. 8.** Substitute y = 3x − 1: 2x + 3x − 1 = 14, so 5x = 15, x = 3 and y = 3(3) − 1 = 8.\n\n**6. C.** Both lines have slope 2 with different intercepts (1 and −5), so they are parallel and never meet. B is the same line written twice (infinitely many solutions). A and D have different slopes (one solution each).\n\n**7. −6.** Multiply the first equation by −2: −6x + 4y = −24. This matches the second equation exactly when a = −6, so the two equations describe the same line. Enter `-6`.\n\n**8. −2.** Distribute: −3x + 6 < 15, so −3x < 9. Dividing by −3 flips the sign: x > −3. The smallest integer greater than −3 is −2. A student who forgets to flip gets x < −3 and has no smallest integer at all, which is a signal something went wrong.\n\n**9. C.** The coefficient of t is the rate of change: each day, the pages left decrease by 45. A describes 1,500; D would be 1,455.\n\n**10. 6.** Expand: ax + 3a − 2x = 4x + 18, so (a − 2)x + 3a = 4x + 18. Matching x coefficients gives a − 2 = 4, so a = 6. Check the constants: 3(6) = 18. Both match, so the equation is an identity.\n\n**Scoring yourself.** Nine or ten correct: move on to harder bank questions. Six to eight: redo the missed ones tomorrow without notes. Five or fewer: return to the skill sections above before more timed practice."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'A Weekly Algebra Routine', '{"markdown":"Algebra rewards frequent, short practice more than occasional marathons.\n\n- **Day 1: Skill review (30 minutes).** Reread one skill section of this module, then do 10 easy and medium bank questions for that skill.\n- **Day 2: Mixed set (30 minutes).** Do 15 mixed Algebra questions in the [question bank](https://practice.sat.schood.online/bank?section_type=math&domain=algebra). Log every miss with the trap that caused it.\n- **Day 3: Desmos day (20 minutes).** Redo five questions you solved by hand, this time with Desmos only, so you know both paths.\n- **Day 4: Hard set (30 minutes).** Do 8–10 [hard Algebra questions](https://practice.sat.schood.online/bank?section_type=math&domain=algebra&difficulty=hard), untimed first, then review each explanation.\n- **Day 5: Error replay (20 minutes).** Redo every question you missed this week without looking at the explanations.\n- **Weekend: Timed module.** Take a timed Math module in the [simulator](https://sat.schood.online) or an official Bluebook practice test, and note where Algebra questions slowed you down.\n\n### What to write in your error log\n\nFor every miss, write the skill, the trap (sign, wrong quantity, units, structure, SPR entry) and the rule that would have prevented it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Priorities by Current Level', '{"markdown":"### Math scores below about 500\n\n- Master one-variable equations with distribution and fractions until they are automatic.\n- Learn to read slope and intercept in context; these questions are early in each module and very learnable.\n- Practise SPR entry rules so that correct work is never marked wrong.\n- Use Desmos for systems now; refine hand methods later.\n\n### Math scores from about 500 to 650\n\n- Make \"answer the quantity asked\" a fixed habit.\n- Learn the no-solution and infinitely-many-solutions rules cold, for both single equations and systems.\n- Practise inequalities in context, including rounding direction for whole-number answers.\n- Start timing yourself on the middle third of each module.\n\n### Math scores above about 650\n\n- Expect parameter questions (find k) and systems written in unusual forms late in the second module.\n- Use elimination to produce combinations such as x + y directly.\n- Use Desmos as a verification tool on every late-module Algebra question.\n- Your remaining Algebra losses are usually careless, not conceptual; your error log is your best study material."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Do I need to memorise formulas for Algebra?\n\nVery few. Slope from two points, slope-intercept form, the slope of Ax + By = C, and the parallel and perpendicular rules cover almost everything. The reference sheet focuses on geometry, so learn these yourself.\n\n### Should I use Desmos for every Algebra question?\n\nNo. Simple equations are faster by hand, and interpretation questions cannot be answered by a calculator. Use Desmos for systems, intercepts, inequalities and checks.\n\n### Why do I keep getting Algebra questions wrong when I know the method?\n\nUsually it is a reading or sign issue, not a knowledge gap. Find the repeat trap in your error log and add one specific check for it.\n\n### Are Algebra questions harder in the second module?\n\nIf you are routed to the harder second module, its questions are on average more difficult, so Algebra items there lean toward parameters, structure and dense contexts. The skills are the same; the precision required is higher."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (29, 'rich_text', 'Related Practice', '{"markdown":"- [Algebra question bank](https://practice.sat.schood.online/bank?section_type=math&domain=algebra): all difficulty levels, filter as you go.\n- [Hard Algebra questions](https://practice.sat.schood.online/bank?section_type=math&domain=algebra&difficulty=hard): upper-module style practice.\n- [Medium Algebra questions](https://practice.sat.schood.online/bank?section_type=math&domain=algebra&difficulty=medium): the bulk of each module.\n- [Today''s practice session](https://practice.sat.schood.online/today): a short mixed set chosen for you.\n- [SAT simulator](https://sat.schood.online): full timed sections."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (30, 'rich_text', 'Next Steps', '{"markdown":"- Continue to [Math: Advanced Math](https://playbook.sat.schood.online/math-advanced-math), the other large Math domain.\n- Learn the calculator techniques used above in [Desmos and calculator strategy](https://playbook.sat.schood.online/desmos-and-calculator-strategy).\n- Plan your time across modules with [Pacing and adaptive modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules).\n- Set a realistic target in [Score goals and study plans](https://playbook.sat.schood.online/score-goals-and-study-plans).\n- If you are new to the test, start with [SAT essentials](https://playbook.sat.schood.online/sat-essentials)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:math-algebra')::uuid
on conflict do nothing;

