-- Module 9: math-problem-solving-data-analysis (31 sections, 3439 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:math-problem-solving-data-analysis')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'math-problem-solving-data-analysis', 'math-problem-solving-data-analysis', 'Math: Problem-Solving and Data Analysis', 'Ratios, rates, units, percentages, one- and two-variable data, probability, margin of error and study design on the digital SAT: what is tested, worked examples, traps, decision rules and a ten-question drill.', 'published', 'public', 'en', 9, 'SAT Problem-Solving and Data Analysis Guide | SAT Playbook', 'Master the SAT Problem-Solving and Data Analysis domain: rates and units, percent change, statistics, scatterplots, two-way tables, margin of error and observational studies versus experiments.', array['SAT', 'SAT Math', 'problem solving and data analysis', 'SAT percentages', 'SAT statistics', 'SAT probability', 'margin of error', 'Digital SAT']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"math-problem-solving-data-analysis","module_group":"domain_math","migration_group":"math","hero_kicker":"Module 9","word_count":3439,"section_count":31,"reading_minutes":17,"estimated_reading_minutes":17,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Data analysis question bank","url":"https://practice.sat.schood.online/bank?section_type=math&domain=problem_solving_data_analysis"},{"label":"Hard data analysis questions","url":"https://practice.sat.schood.online/bank?section_type=math&domain=problem_solving_data_analysis&difficulty=hard"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"},{"label":"Full SAT simulator","url":"https://sat.schood.online"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:math-problem-solving-data-analysis:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Domain Matters', '{"markdown":"Problem-Solving and Data Analysis (PSDA) is about **15% of the Math section, roughly 5 to 7 questions** across the two modules. That is smaller than Algebra or Advanced Math, but it is one of the most learnable domains on the test. The questions use a short list of ideas: rates and units, percentages, averages and spread, scatterplots and models, probability from tables, and how to judge a study or survey.\n\nMany PSDA questions are set in a context, and College Board notes that about 30% of all Math questions are in context. The difficulty is rarely the arithmetic. It is reading carefully: percent **of what**, rate **per what**, a conclusion about **which group**. Students who slow down for one extra sentence often turn this domain into reliable points.\n\n**If you master the traps in this module, PSDA questions become some of the safest points in each module.**"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Solve rate, ratio, proportion and unit conversion problems without unit errors.","Compute percentages, percent change and successive percent changes.","Find and compare mean, median, mode and range, and reason about standard deviation.","Read histograms, dot plots, box plots and frequency tables.","Interpret a line of best fit, its slope, intercept and residuals.","Tell linear growth from exponential growth in a context.","Compute probabilities and conditional probabilities from two-way tables.","Interpret a sample estimate with a margin of error.","Decide what conclusions an observational study or an experiment supports."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where PSDA Sits in the Math Section', '{"markdown":"| Fact | What it means here |\n|---|---|\n| About 15% of Math, 5–7 questions | Usually two to four PSDA questions per module |\n| Questions run easiest to hardest in each module | Early PSDA items are quick rate or percent questions; later ones involve data reasoning or study design |\n| About 75% multiple choice, 25% student-produced response | Rates, percents and probabilities often appear as student-produced responses |\n| Calculator allowed throughout | Desmos lists and regressions help with data questions |\n\n**The official skills are:** ratios, rates, proportional relationships and units; percentages; one-variable data (distributions and measures of centre and spread); two-variable data (models and scatterplots); probability and conditional probability; inference from sample statistics and margin of error; and evaluating statistical claims (observational studies and experiments)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'Skill 1: Ratios, Rates and Proportions', '{"markdown":"A **ratio** compares two quantities; a **rate** is a ratio with different units, such as kilometres per hour; a **proportion** says two ratios are equal.\n\n**Method:**\n\n1. Write the rate with its units, for example 240 bottles per 60 minutes.\n2. Convert to the unit the question needs, for example 4 bottles per minute.\n3. Multiply or divide, keeping the units visible so they cancel correctly.\n\n**Unit check:** if the units of your final answer are not the units the question asks for, you have made an error. Writing units next to every number is the fastest way to catch it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Worked Example 1: A Rate With a Unit Change', '{"markdown":"A machine fills 240 bottles per hour. At this rate, how many bottles does it fill in 35 minutes?\n\nA) 84  B) 140  C) 411  D) 8,400\n\n**Solution:** 240 bottles per hour is 240 ÷ 60 = 4 bottles per minute. In 35 minutes: 4 × 35 = **140, choice B**.\n\n**Why the others are tempting:**\n\n- **A (84)** treats 35 minutes as 0.35 hours. Minutes are sixtieths of an hour, not hundredths.\n- **C (411)** divides 60 by 35 instead of multiplying by the fraction of an hour.\n- **D (8,400)** multiplies 240 by 35, mixing hours and minutes."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Skill 2: Percentages', '{"markdown":"Three forms cover almost every question:\n\n- **Part = percent × whole.** 30% of 40 is 0.30 × 40 = 12.\n- **Percent change = (new − old) ÷ old × 100.** Always divide by the **original** value.\n- **Multipliers:** an increase of p% multiplies by (1 + p/100); a decrease of p% multiplies by (1 − p/100).\n\nSuccessive changes multiply. A 20% increase followed by a 20% decrease is 1.2 × 0.8 = 0.96, a net **decrease of 4%**, not zero.\n\n**Percentage points versus percent:** a rate rising from 40% to 50% has risen by 10 percentage points, which is a 25% increase relative to the original 40%. Questions test this distinction deliberately."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Worked Example 2: Successive Percent Changes', '{"markdown":"A jacket costs $50. Its price is raised by 20%, and later the new price is reduced by 20%. The final price is what percent of the original price?\n\nA) 80%  B) 96%  C) 100%  D) 104%\n\n**Solution:** 50 × 1.2 = 60, then 60 × 0.8 = 48. Since 48 ÷ 50 = 0.96, the answer is **96%, choice B**.\n\n**Traps:** C assumes the two changes cancel. A applies only the decrease. D adds the changes in the wrong direction. The multiplier method, 1.2 × 0.8, avoids all three."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Worked Example 3: Percent of What?', '{"markdown":"In a science club, 30% of the members are seniors. There are 12 seniors in the club. How many members does the club have?\n\nA) 3.6  B) 15.6  C) 36  D) 40\n\n**Solution:** 0.30 × total = 12, so total = 12 ÷ 0.30 = **40, choice D**.\n\n**Traps:** A computes 30% of 12; B adds that to 12; C is a near-miss for students who estimate \"about three times 12\". The question gives the part and the percent, so divide."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Skill 3: One-Variable Data', '{"markdown":"| Measure | What it is | Sensitive to outliers? |\n|---|---|---|\n| Mean | Sum ÷ number of values | Yes, strongly |\n| Median | Middle value when ordered (average of the two middle values if the count is even) | No, resistant |\n| Mode | Most frequent value | No |\n| Range | Maximum − minimum | Yes, extremely |\n| Standard deviation | Typical distance of values from the mean | Yes |\n\n**Reading frequency tables, dot plots and histograms:** the count of data values is the sum of the frequencies, not the number of categories. To find the median, find the position of the middle value (for 20 values, the 10th and 11th) and count through the frequencies.\n\n**Standard deviation on the SAT** is almost always conceptual: which data set is more spread out from its mean? You will rarely compute it. Data clustered tightly around the mean has a small standard deviation; data spread widely has a large one."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Worked Example 4: Mean Versus Median From a Frequency Table', '{"markdown":"A teacher records the number of books each of 20 students read over a holiday.\n\n| Books read | 2 | 3 | 4 | 5 |\n|---|---|---|---|---|\n| Number of students | 3 | 5 | 8 | 4 |\n\nWhich statement is true?\n\nA) The mean is greater than the median.  B) The mean is less than the median.  C) The mean equals the median.  D) The median is 3.5.\n\n**Solution:** total books = 2(3) + 3(5) + 4(8) + 5(4) = 6 + 15 + 32 + 20 = 73, so the mean is 73 ÷ 20 = 3.65. With 20 values the median is the average of the 10th and 11th values. The first 3 values are 2s, the next 5 (positions 4 to 8) are 3s, and positions 9 to 16 are 4s, so both the 10th and 11th values are 4. The median is 4. **The mean is less than the median, choice B.**\n\n**Trap:** D finds the middle of the four categories (between 3 and 4) instead of the middle student."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Skill 4: Two-Variable Data and Models', '{"markdown":"A scatterplot shows pairs of values. A **line of best fit** models the trend.\n\n- **Slope:** the predicted change in y for each one-unit increase in x. In context, say it with units: \"about 2.4 points per additional hour\".\n- **y-intercept:** the predicted y when x = 0. It may or may not be meaningful in context.\n- **Residual:** actual y − predicted y. Positive means the point lies above the line.\n- **Association is not causation.** A scatterplot shows a relationship in data, not why it exists.\n\n**Linear versus exponential:** linear models add the same amount each period; exponential models multiply by the same factor each period. \"Increases by 60 per year\" is linear. \"Increases by 6% per year\" is exponential: P = P₀(1.06)^t."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Worked Example 5: Interpreting a Line of Best Fit', '{"markdown":"For a group of students, the line of best fit for test score y against hours of study x is y = 2.4x + 15. One student studied for 10 hours and scored 44.\n\n(a) What does 2.4 mean? (b) What is this student''s residual?\n\n**Solution:** (a) For each additional hour of study, the model predicts a score about 2.4 points higher. (b) The predicted score is 2.4(10) + 15 = 39. The residual is 44 − 39 = **5**: the student scored 5 points above the model''s prediction.\n\n**Traps:** saying \"studying causes a 2.4-point increase\" overstates a model built from observational data; calling the residual −5 subtracts in the wrong order."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Worked Example 6: Linear or Exponential?', '{"markdown":"A town has 1,000 residents. Plan A predicts an increase of 6% per year; Plan B predicts an increase of 60 residents per year. To the nearest whole number, how many more residents does Plan A predict than Plan B after 3 years?\n\n**Solution:** Plan A: 1,000 × 1.06³ ≈ 1,191.016, about 1,191. Plan B: 1,000 + 3(60) = 1,180. The difference is **11**.\n\n**Insight:** for the first year both plans add 60 residents. Exponential growth pulls ahead because each year''s 6% is taken of a larger number."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Skill 5: Probability and Conditional Probability', '{"markdown":"**Probability = favourable outcomes ÷ total possible outcomes.** With a two-way table, the key is choosing the right **total**.\n\n- \"A randomly chosen student\" → the grand total.\n- \"A randomly chosen student **who prefers tea**\" → the tea total only. This is conditional probability: the condition shrinks the denominator.\n- \"Given that\", \"of those who\", \"among the\" all signal a conditional probability."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Worked Example 7: Conditional Probability From a Table', '{"markdown":"A survey of 120 students recorded grade and drink preference.\n\n| | Prefers tea | Prefers coffee | Total |\n|---|---|---|---|\n| Grade 11 | 18 | 42 | 60 |\n| Grade 12 | 27 | 33 | 60 |\n| Total | 45 | 75 | 120 |\n\nA student who prefers tea is chosen at random. What is the probability that the student is in grade 12? (Student-produced response.)\n\n**Solution:** the condition is \"prefers tea\", so the denominator is 45. There are 27 grade 12 tea drinkers: 27 ÷ 45 = **3/5**, which can be entered as 3/5 or .6.\n\n**Common wrong answers:** 27/120 (the whole survey as the denominator), 27/60 (all grade 12 students as the denominator) and 45/120 (the probability of preferring tea)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Skill 6: Samples and Margin of Error', '{"markdown":"When a survey uses a **random sample**, its result estimates the value for the whole population it was drawn from. A **margin of error** describes the uncertainty: an estimate of 56% with a margin of error of 4 percentage points means that values from 52% to 60% are plausible for the population.\n\nKey ideas the SAT tests:\n\n- **The estimate applies to the population sampled**, not to a different population.\n- **The true value is not guaranteed to be inside the interval**; the interval gives plausible values.\n- **Larger random samples generally give smaller margins of error.**\n- **A non-random sample** (volunteers, one classroom, people outside one shop) cannot be generalised reliably."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked Example 8: Reading a Margin of Error', '{"markdown":"A random sample of 400 voters in a city found that 56% support a new park, with a margin of error of 4 percentage points. Which conclusion is best supported?\n\nA) Exactly 56% of the city''s voters support the park.\nB) It is plausible that between 52% and 60% of the city''s voters support the park.\nC) Between 52% and 60% of all voters in the country support the park.\nD) If the sample were doubled, the result would certainly be 56%.\n\n**Answer: B.** A ignores the uncertainty. C generalises beyond the population sampled (the city). D claims certainty that no sample can give; a larger sample would usually narrow the margin of error, not fix the estimate."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Skill 7: Evaluating Statistical Claims', '{"markdown":"Two design features decide what a study can conclude:\n\n| Design feature | What it allows |\n|---|---|\n| **Random sampling** from a population | Generalising results to that population |\n| **Random assignment** to treatment groups | Concluding that the treatment caused a difference (for the participants) |\n| Neither (observational, volunteers) | Describing an association in this group only |\n\n**Decision rule:** a cause-and-effect conclusion needs random assignment. A conclusion about a larger population needs random sampling from that population. If a study has random assignment but used volunteers, it supports causation for those volunteers, not for everyone."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Worked Example 9: What Does the Study Show?', '{"markdown":"Researchers asked 300 volunteers at a gym how many hours they slept and how often they exercised. People who exercised more tended to sleep more. Which conclusion is appropriate?\n\nA) Exercise causes people to sleep longer.\nB) Among these volunteers, more exercise was associated with more sleep.\nC) All adults who exercise more sleep longer.\nD) Sleeping longer causes people to exercise more.\n\n**Answer: B.** The study is observational (no random assignment), so A and D claim causation that the design cannot support. The participants were volunteers at one gym, not a random sample of adults, so C generalises too far."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Common PSDA Traps', '{"markdown":"- **Dividing by the wrong total** in percent change or probability.\n- **Treating successive percent changes as additive.**\n- **Confusing percentage points with percent.**\n- **Minutes as decimals of an hour** (35 minutes is not 0.35 hours).\n- **Counting categories instead of data values** in frequency tables.\n- **Assuming the mean and median are equal** without checking for skew or outliers.\n- **Reading a model''s slope as a cause.**\n- **Generalising a survey** beyond the population it sampled.\n- **Claiming causation** from an observational study."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Decision Rules', '{"markdown":"1. **Write units on every number** in rate problems.\n2. **Underline the denominator word** in probability questions: \"of those who…\", \"given…\".\n3. **Use multipliers** for any percent change, especially successive ones.\n4. **For statistics conclusions, ask two questions:** was there random sampling? was there random assignment?\n5. **Use Desmos lists** (`mean(L)`, `median(L)`) when a data set has more than about six values; do small sets by hand.\n6. **Use regression** only when the question asks you to find or compare a model the problem does not give."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Student-Produced Response Tips', '{"markdown":"- Probabilities can be entered as fractions such as 3/7, or as decimals that fill the available places, such as .4285 or .4286.\n- **Do not type a percent sign.** If the answer is 15%, read the question: does it want 15 (the percent) or 0.15 (the decimal)? Enter what the question''s wording requires.\n- Money answers are entered without the $ sign or commas: 48.6 or 48.60, not $48.60.\n- Round only when the question tells you to, and to the place it names."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Timing Guidance', '{"markdown":"PSDA questions in the first half of a module, such as rates and simple percents, should take **45 to 75 seconds**. Table-based probability and data questions usually take **about 90 seconds**. Study-design questions are mostly reading and should take **under a minute** once you know the decision rule. If a later PSDA question involves a long table, read the question first so you know which row and column you need before scanning the data."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Drill: Problem-Solving and Data Analysis', '{"markdown":"1. A cyclist rides 7.5 kilometres in 50 minutes. What is the average speed in kilometres per hour?\n2. A membership fee rises from $80 to $92. By what percent did the fee increase?\n3. A $60 item is discounted by 25%, and then 8% sales tax is added to the discounted price. What is the final cost in dollars?\n4. The mean of five numbers is 14. Four of the numbers are 10, 12, 15 and 18. What is the fifth number?\n5. What is the median of 3, 9, 4, 12, 7, 10?\n6. In a course, Section A has 24 students who passed and 6 who failed; Section B has 18 who passed and 12 who failed. A student who passed is chosen at random. What is the probability the student is from Section B?\n7. A random sample of a school''s students found a mean of 6.2 hours of sleep per night, with a margin of error of 0.4 hours. Which range of values is plausible for the mean of all students at the school?\n8. Researchers randomly assigned 80 volunteers to use a new study app or a standard textbook for a month. The app group scored higher on average. What can be concluded?\n9. The line of best fit for a data set is y = −0.8x + 50. What is the predicted value of y when x = 25?\n10. Data set P is 10, 10, 10, 10, 10. Data set Q is 6, 8, 10, 12, 14. Compare their means and standard deviations."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"1. **9.** 7.5 km in 50 minutes is 7.5 ÷ 50 = 0.15 km per minute; × 60 = 9 km per hour.\n2. **15%.** (92 − 80) ÷ 80 = 0.15. Dividing by 92 (about 13%) uses the new value as the base.\n3. **48.6** (or 48.60). 60 × 0.75 = 45, then 45 × 1.08 = 48.6. Subtracting 25% and adding 8% to get 83% of 60 (49.8) is the additive trap.\n4. **15.** The five numbers sum to 5 × 14 = 70; the four known numbers sum to 55; 70 − 55 = 15.\n5. **8.** Ordered: 3, 4, 7, 9, 10, 12. The two middle values are 7 and 9; their average is 8. The mean is 7.5, a common mix-up.\n6. **3/7** (or .4285, .4286, 0.428, 0.429). The condition \"passed\" gives 24 + 18 = 42 students, and 18 are in Section B. Using 30 (Section B only) or 60 (everyone) as the denominator gives a wrong answer.\n7. **5.8 to 6.6 hours.** 6.2 ± 0.4. The conclusion applies to students at that school, the population sampled.\n8. **Using the app caused higher average scores for these volunteers.** Random assignment supports a causal conclusion, but because the participants were volunteers rather than a random sample, it does not justify generalising to all students.\n9. **30.** −0.8(25) + 50 = −20 + 50 = 30.\n10. **Same mean (10), but Q has the larger standard deviation.** Every value in P equals the mean, so its standard deviation is 0; Q''s values spread out from 10."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Practice Plan for This Domain', '{"markdown":"A focused two-week routine:\n\n- **Days 1–2:** rates, units and percentages. Twenty bank questions; write units on every number.\n- **Days 3–4:** one-variable data with tables, dot plots and box plots.\n- **Days 5–6:** scatterplots, models, linear versus exponential.\n- **Days 7–8:** two-way tables and conditional probability.\n- **Days 9–10:** margin of error and study design. Write the two-question rule (sampling? assignment?) at the top of your scratch paper.\n- **Days 11–14:** mixed timed sets of ten PSDA questions in about 12 minutes, then redo every miss from scratch."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Level-Specific Priorities', '{"markdown":"**Math section under about 500:** master rates with units, the percent formulas and mean versus median. These appear early in modules and are very learnable.\n\n**About 500 to 650:** eliminate the classic traps: successive percents, percentage points, conditional denominators and causation claims. Practise reading the question twice.\n\n**Above about 650:** expect the harder versions in the second module: multi-step unit conversions, data with outliers, comparisons of models and subtle study-design conclusions. Accuracy here should be near perfect, because these questions are about careful reading more than difficult math.\n\nThese score ranges are Schood planning guides, not official bands."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'callout', 'Spot the Trap', '{"label":"Read the last sentence twice","body":"Most wrong answers in this domain come from answering a slightly different question from the one asked: the percent of the wrong whole, the probability with the wrong denominator, a conclusion about the wrong population. Before you choose, reread the final sentence of the question and say aloud, in your head, exactly what quantity and which group it asks about."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (29, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Do I need to calculate standard deviation?\nRarely. Most SAT questions on standard deviation ask which data set has more spread, which you can judge by how far values sit from the mean.\n\n### Is a box plot on the test?\nIt can be. Know that a box plot shows the minimum, first quartile, median, third quartile and maximum, and that the box spans the middle half of the data.\n\n### When should I use Desmos in this domain?\nFor data sets with many values (lists and statistics functions) and for finding or comparing models (regression). Rates, percents and probabilities from tables are usually faster by hand.\n\n### What is the difference between random sampling and random assignment?\nRandom sampling chooses who is studied, which supports generalising to the population. Random assignment decides who gets which treatment, which supports cause-and-effect conclusions.\n\n### How many PSDA questions will I see?\nAbout 5 to 7 across the whole Math section, according to College Board''s specifications."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (30, 'rich_text', 'Related Practice', '{"markdown":"- [Data analysis question bank](https://practice.sat.schood.online/bank?section_type=math&domain=problem_solving_data_analysis): filter by difficulty and work in short sets.\n- [Hard data analysis questions](https://practice.sat.schood.online/bank?section_type=math&domain=problem_solving_data_analysis&difficulty=hard): second-module style items.\n- [Today''s practice session](https://practice.sat.schood.online/today): mixed daily practice.\n- [SAT Simulator](https://sat.schood.online): see PSDA questions in a full timed test."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (31, 'rich_text', 'Next Steps', '{"markdown":"1. Learn Desmos lists and regressions in [Desmos and Calculator Strategy](https://playbook.sat.schood.online/desmos-and-calculator-strategy).\n2. Strengthen the larger Math domains in [Algebra](https://playbook.sat.schood.online/math-algebra) and [Advanced Math](https://playbook.sat.schood.online/math-advanced-math).\n3. Complete the Math set with [Geometry and Trigonometry](https://playbook.sat.schood.online/math-geometry-trigonometry).\n4. The quantitative evidence questions in [Information and Ideas](https://playbook.sat.schood.online/reading-writing-information-ideas) use the same graph-reading skills."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:math-problem-solving-data-analysis')::uuid
on conflict do nothing;

