-- Module 10: math-geometry-trigonometry (33 sections, 3138 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:math-geometry-trigonometry')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'math-geometry-trigonometry', 'math-geometry-trigonometry', 'Math: Geometry and Trigonometry', 'Area and volume, lines, angles and triangles, right-triangle trigonometry and circles on the digital SAT: what the reference sheet gives you and what it does not, worked examples, traps and a ten-question drill.', 'published', 'public', 'en', 10, 'SAT Geometry and Trigonometry Guide | SAT Playbook', 'Master SAT Geometry and Trigonometry: the reference sheet, area and volume, parallel lines and similar triangles, special right triangles, SOH-CAH-TOA, radians, circle equations, arcs and sectors.', array['SAT', 'SAT Math', 'SAT geometry', 'SAT trigonometry', 'circle equation', 'special right triangles', 'radians', 'Digital SAT']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"math-geometry-trigonometry","module_group":"domain_math","migration_group":"math","hero_kicker":"Module 10","word_count":3138,"section_count":33,"reading_minutes":16,"estimated_reading_minutes":16,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Geometry and trigonometry question bank","url":"https://practice.sat.schood.online/bank?section_type=math&domain=geometry_trig"},{"label":"Hard geometry questions","url":"https://practice.sat.schood.online/bank?section_type=math&domain=geometry_trig&difficulty=hard"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"},{"label":"Full SAT simulator","url":"https://sat.schood.online"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:math-geometry-trigonometry:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Domain Matters', '{"markdown":"Geometry and Trigonometry is about **15% of the Math section, roughly 5 to 7 questions** across both modules. It is the smallest domain alongside Problem-Solving and Data Analysis, but it is unusually rewarding to study: the set of facts tested is short, a good part of it is printed on the reference sheet, and the rest fits on one page of notes.\n\nWhat makes these questions hard is rarely knowledge. It is **seeing the structure**: spotting the similar triangles, noticing that a radius is also a side of a right triangle, or completing the square to find a circle''s centre. This module gives you the facts, the structures to look for and the traps that catch strong students."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Use the reference sheet confidently and know what it does not include.","Find areas and volumes of standard and composite shapes.","Use angle relationships with parallel lines and triangles.","Solve problems with similar and congruent triangles.","Apply the Pythagorean theorem and the special right triangles.","Use sine, cosine and tangent, including sin x = cos(90° − x).","Convert between degrees and radians.","Work with circle equations, including completing the square.","Find arc lengths, sector areas and inscribed angles."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where This Domain Sits in the Math Section', '{"markdown":"| Fact | What it means here |\n|---|---|\n| About 15% of Math, 5–7 questions | Usually two to four geometry or trigonometry questions per module |\n| Easiest to hardest across each module | Early items are direct formula use; later items combine ideas, such as circles with right triangles |\n| Figures are drawn to scale unless stated | You can use a figure to sanity-check an answer |\n| Reference sheet and calculator always available | Formulas and computation are not the bottleneck; setup is |\n\n**The official skills are:** area and volume; lines, angles and triangles; right triangles and trigonometry; and circles. The Bluebook directions state that, unless otherwise indicated, figures are drawn to scale and lie in a plane."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'The Reference Sheet: What It Gives You', '{"markdown":"The Bluebook reference sheet lists:\n\n- **Circle:** area A = πr², circumference C = 2πr.\n- **Rectangle:** A = lw. **Triangle:** A = ½bh.\n- **Pythagorean theorem:** c² = a² + b².\n- **Special right triangles:** 30°-60°-90° with sides x, x√3 and 2x; 45°-45°-90° with sides s, s and s√2.\n- **Volumes:** rectangular prism V = lwh; cylinder V = πr²h; sphere V = (4/3)πr³; cone V = (1/3)πr²h; rectangular pyramid V = (1/3)lwh.\n- **Facts:** a circle has 360 degrees of arc and 2π radians of arc; the angles of a triangle sum to 180 degrees.\n\nOpen it once early in each Math module so you know where it is, and use it rather than trusting a half-remembered formula."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'What the Reference Sheet Does Not Give You', '{"markdown":"**These are not on the sheet, so learn them:**\n\n| Fact | Formula or rule |\n|---|---|\n| Circle equation | (x − h)² + (y − k)² = r², centre (h, k), radius r |\n| Arc length | (central angle ÷ 360°) × 2πr, or r × θ with θ in radians |\n| Sector area | (central angle ÷ 360°) × πr² |\n| Inscribed angle | Half the central angle that subtends the same arc |\n| Tangent line | Perpendicular to the radius at the point of tangency |\n| Trig ratios | sin = opposite/hypotenuse, cos = adjacent/hypotenuse, tan = opposite/adjacent |\n| Complementary angles | sin x = cos(90° − x) |\n| Degrees and radians | 180° = π radians |\n| Similar figures | Lengths scale by k, areas by k², volumes by k³ |\n| Parallel lines | Corresponding and alternate interior angles are equal; same-side interior angles sum to 180° |\n| Exterior angle of a triangle | Equals the sum of the two remote interior angles |"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Skill 1: Area and Volume', '{"markdown":"Most area and volume questions use one formula; harder ones combine shapes or ask how a change in dimensions changes the result.\n\n**Composite shapes:** split the figure into pieces you know, find each area, and add or subtract.\n\n**Scaling:** if every length is multiplied by k, the area is multiplied by k² and the volume by k³. Doubling the radius of a sphere multiplies its volume by 8.\n\n**Units:** areas are in square units and volumes in cubic units. If a question changes units, convert lengths first, then compute."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Worked Example 1: A Composite Area', '{"markdown":"A garden is a rectangle 10 metres long and 6 metres wide, with a semicircle attached along one of its 6-metre sides, outside the rectangle. What is the total area, to the nearest square metre?\n\nA) 74  B) 88  C) 117  D) 67\n\n**Solution:** rectangle 10 × 6 = 60. The semicircle has diameter 6, so radius 3, and area ½π(3²) = 4.5π ≈ 14.14. Total ≈ 74.14, so **74, choice A**.\n\n**Why the others are tempting:**\n\n- **B (88)** uses a full circle of radius 3 instead of a semicircle.\n- **C (117)** uses the diameter 6 as the radius in the semicircle.\n- **D (67)** uses a quarter circle instead of a semicircle."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Worked Example 2: Cylinder and Cone', '{"markdown":"A cylinder and a cone each have radius 3 and height 8. How many times the volume of the cone is the volume of the cylinder?\n\n**Solution:** cylinder πr²h = π(9)(8) = 72π; cone (1/3)π(9)(8) = 24π. The ratio is **3**. In general, a cylinder holds three times the volume of a cone with the same base and height, a fact visible directly from the two reference-sheet formulas."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Skill 2: Lines, Angles and Triangles', '{"markdown":"Facts to apply quickly:\n\n- **Vertical angles** are equal; angles on a straight line sum to 180°.\n- **Parallel lines cut by a transversal:** corresponding angles and alternate interior angles are equal; same-side (co-interior) angles sum to 180°.\n- **Triangle angle sum** is 180°; an exterior angle equals the sum of the two remote interior angles.\n- **Isosceles triangle:** equal sides face equal angles.\n- **Similar triangles** have equal angles and proportional sides. Two pairs of equal angles are enough to prove similarity.\n- **Congruent triangles** are the same shape and size.\n\n**The key habit:** when a figure has parallel lines or a line parallel to one side of a triangle, look for similar triangles straight away."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Worked Example 3: Parallel Lines and a Transversal', '{"markdown":"Two parallel lines are cut by a transversal. Two alternate interior angles measure (3x + 10)° and (5x − 30)°. What is the measure of each angle?\n\n**Solution:** alternate interior angles are equal, so 3x + 10 = 5x − 30, giving x = 20. Each angle is 3(20) + 10 = **70°**.\n\n**Trap:** treating the angles as same-side interior angles and setting their sum to 180° gives x = 25 and angles of 85° and 95°, which are not equal and so cannot be alternate interior angles. Identify the angle relationship before writing the equation."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Worked Example 4: Similar Triangles', '{"markdown":"In triangle ABC, point D lies on AB and point E lies on AC so that DE is parallel to BC. AD = 4, DB = 6 and DE = 5. What is BC?\n\n**Solution:** because DE ∥ BC, triangle ADE is similar to triangle ABC. The scale factor is AB ÷ AD = (4 + 6) ÷ 4 = 2.5. So BC = 5 × 2.5 = **12.5**.\n\n**Trap:** using DB instead of AB in the ratio gives 5 × 6/4 = 7.5. The corresponding side to AD is the **whole** side AB, not the piece DB."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Skill 3: Right Triangles', '{"markdown":"**Pythagorean theorem:** a² + b² = c², where c is the hypotenuse, the side opposite the right angle.\n\n**Common Pythagorean triples** save time: 3-4-5, 5-12-13, 8-15-17, 7-24-25, and their multiples such as 6-8-10.\n\n**Special right triangles** from the reference sheet:\n\n- **45°-45°-90°:** legs s and s, hypotenuse s√2. A square''s diagonal splits it into two of these.\n- **30°-60°-90°:** short leg x (opposite 30°), long leg x√3 (opposite 60°), hypotenuse 2x. An equilateral triangle''s height splits it into two of these."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Worked Example 5: The Ladder', '{"markdown":"A 13-foot ladder leans against a vertical wall. The foot of the ladder is 5 feet from the wall on level ground. How high up the wall does the ladder reach?\n\n**Solution:** the ladder is the hypotenuse: h² + 5² = 13², so h² = 144 and **h = 12 feet**. Recognising the 5-12-13 triple makes this instant."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Worked Example 6: A 30-60-90 Triangle', '{"markdown":"A right triangle has a 30° angle and a hypotenuse of 10. What is its area?\n\n**Solution:** the hypotenuse is 2x = 10, so x = 5 (short leg) and the long leg is 5√3. Area = ½ × 5 × 5√3 = 12.5√3 ≈ **21.65**.\n\n**Trap:** taking 10 as a leg rather than the hypotenuse. Mark the hypotenuse on your sketch first."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Skill 4: Trigonometry', '{"markdown":"For an acute angle in a right triangle:\n\n| Ratio | Definition |\n|---|---|\n| sin θ | opposite ÷ hypotenuse |\n| cos θ | adjacent ÷ hypotenuse |\n| tan θ | opposite ÷ adjacent |\n\n**The complementary-angle fact** appears often: in a right triangle, the two acute angles add to 90°, and **the sine of one equals the cosine of the other**. So sin x = cos(90° − x).\n\n**Radians:** 180° = π radians. To convert degrees to radians, multiply by π/180; radians to degrees, multiply by 180/π. Common values: 30° = π/6, 45° = π/4, 60° = π/3, 90° = π/2.\n\n**Calculator mode:** if you compute a trig value in Desmos, check whether it is in degree or radian mode first. In degree mode, sin(30) is 0.5."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Worked Example 7: Complementary Angles', '{"markdown":"In right triangle ABC, the right angle is at C and sin A = 0.6. What is cos B?\n\n**Solution:** angles A and B are complementary, so cos B = sin A = **0.6**. No side lengths are needed.\n\nA longer route also works: sin A = 0.6 = 3/5 means the side opposite A is 3k and the hypotenuse 5k. The side opposite A is adjacent to B, so cos B = 3k ÷ 5k = 0.6. Knowing the shortcut saves about a minute."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked Example 8: Degrees to Radians', '{"markdown":"What is 150° in radians?\n\n**Solution:** 150 × π/180 = **5π/6**. As a check, 150° is a little less than 180°, and 5π/6 is a little less than π."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Skill 5: Circles', '{"markdown":"The standard form of a circle is **(x − h)² + (y − k)² = r²**, with centre (h, k) and radius r. Note the signs: (x + 2)² means h = −2.\n\n**Completing the square** turns a general equation into standard form:\n\n1. Group x-terms and y-terms; move the constant to the right.\n2. For each variable, take half its coefficient, square it, and add it to both sides.\n3. Factor each group as a perfect square.\n\n**Arcs and sectors:** a central angle of θ degrees cuts off θ/360 of the circle, so the arc length is (θ/360) × 2πr and the sector area is (θ/360) × πr². In radians, arc length is simply rθ.\n\n**Angles:** an inscribed angle is half of the central angle that subtends the same arc. An angle inscribed in a semicircle is a right angle. A tangent is perpendicular to the radius at the point where it touches."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Worked Example 9: Completing the Square', '{"markdown":"What are the centre and radius of the circle x² + y² − 6x + 8y − 11 = 0?\n\n**Solution:** group and move the constant: (x² − 6x) + (y² + 8y) = 11. Add 9 (half of −6, squared) and 16 (half of 8, squared) to both sides: (x − 3)² + (y + 4)² = 36. **Centre (3, −4), radius 6.**\n\n**Traps:** writing the centre as (−3, 4) by copying signs from the expanded equation, and giving the radius as 36 (that is r²). Forgetting to add 9 and 16 to the right-hand side gives r² = 11."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Worked Example 10: Arc Length and Sector Area', '{"markdown":"A circle has radius 9. A central angle measures 80°. Find the arc length and the sector area.\n\n**Solution:** arc = (80/360) × 2π(9) = **4π ≈ 12.57**. Sector area = (80/360) × π(81) = **18π ≈ 56.55**.\n\n**Trap:** using the full circumference or area without the fraction of the circle, or using the diameter where the radius belongs."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Worked Example 11: Inscribed and Central Angles', '{"markdown":"Points A, B and C lie on a circle with centre O. The central angle AOB measures 100°, and C is on the major arc (the longer arc from A to B). What is the measure of angle ACB?\n\n**Solution:** angle ACB is an inscribed angle subtending the same arc AB as the central angle AOB, so it is half as large: **50°**.\n\n**Traps:** answering 100° treats the inscribed angle as equal to the central angle; answering 130° (half of 260°) uses the major arc instead of the arc that the angle actually subtends. Trace the two sides of the inscribed angle to see which arc lies between them."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Common Geometry Traps', '{"markdown":"- **Diameter used as radius**, or the reverse.\n- **Reading r² as r** in a circle equation.\n- **Sign errors in the centre** of a circle: (x + 5)² means the centre''s x-coordinate is −5.\n- **Using a piece of a side** instead of the whole side in similar triangles.\n- **Assuming a triangle is right-angled** because it looks like one; use only what is given or marked.\n- **Wrong calculator mode** in trig problems.\n- **Forgetting to scale area by k² and volume by k³** when dimensions change.\n- **Answering the angle measure when the question asks for x**, or the reverse."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Decision Rules', '{"markdown":"1. **Draw or redraw the figure** on scratch paper and label every given value. If there is no figure, sketch one.\n2. **Mark right angles and parallel lines** immediately; they trigger the Pythagorean theorem, trig ratios or similar triangles.\n3. **Look for hidden right triangles** in circles (radius to a tangent point, a chord bisected by a radius) and in rectangles (diagonals).\n4. **Check the reference sheet** for any formula you are less than certain of.\n5. **Use Desmos for circle equations** if completing the square by hand is slow: type the equation and read the centre and radius from the graph.\n6. **Estimate from the figure** when it is drawn to scale. An answer that contradicts the picture is probably wrong."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Student-Produced Response Tips', '{"markdown":"- If a question asks for \"the value of k\" where the answer is kπ, enter only k. For an arc of 4π, the answer to \"k\" is 4.\n- **Do not type π, °, or square root symbols.** If a question wants a decimal, enter the decimal using the rounding rule; if it gives a form such as a√b, enter just the requested part.\n- For an exact fraction such as 5/6, the fraction is safest; a decimal must use all available places (.8333)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Timing Guidance', '{"markdown":"Direct formula questions (area of a shape, a single Pythagorean step) should take **under a minute**. Similar triangles and trig questions usually take **60 to 90 seconds**. Circle questions that require completing the square or combining a circle with a triangle are typically among the later, harder questions; budget **2 to 3 minutes**, and if no structure appears after a minute, guess, mark and move on."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Drill: Geometry and Trigonometry', '{"markdown":"1. Two angles of a triangle measure 47° and 68°. What is the third angle?\n2. A triangle has base 14 and height 9. What is its area?\n3. A sphere has radius 3. Its volume is kπ. What is k?\n4. Two similar triangles have corresponding sides in the ratio 1 : 3. The smaller has area 5. What is the area of the larger?\n5. A right triangle has legs 8 and 15. What is the hypotenuse?\n6. A 45°-45°-90° triangle has hypotenuse 6√2. What is the length of each leg?\n7. In a right triangle, tan θ = 3/4 and the hypotenuse is 20. What is the length of the side opposite θ?\n8. Is the point (5, 5) on the circle (x + 2)² + (y − 5)² = 49?\n9. A circle has radius 12. A central angle measures π/3 radians. The arc length is kπ. What is k?\n10. Convert 2π/5 radians to degrees."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"1. **65°.** 180 − 47 − 68 = 65.\n2. **63.** ½ × 14 × 9 = 63. Forgetting the ½ gives 126.\n3. **36.** (4/3)π(3³) = (4/3)(27)π = 36π.\n4. **45.** Areas scale by the square of the side ratio: 3² = 9, and 9 × 5 = 45. Answering 15 scales by 3 instead of 9.\n5. **17.** 8² + 15² = 64 + 225 = 289 = 17². This is the 8-15-17 triple.\n6. **6.** In a 45°-45°-90° triangle the hypotenuse is s√2, so s = 6.\n7. **12.** tan θ = 3/4 means the sides are 3k, 4k and 5k. With 5k = 20, k = 4, so the opposite side is 12 and the adjacent side is 16.\n8. **Yes.** The centre is (−2, 5) and the radius is 7. The point (5, 5) is 7 units to the right of the centre, so it lies on the circle. Reading the centre as (2, −5) is the sign trap.\n9. **4.** In radians, arc length = rθ = 12 × π/3 = 4π.\n10. **72°.** (2π/5) × (180/π) = 72."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Practice Plan for This Domain', '{"markdown":"- **Week 1, days 1–2:** read the reference sheet and write your own \"not on the sheet\" card from this module.\n- **Days 3–4:** angles, parallel lines and similar triangles; 15 bank questions.\n- **Days 5–6:** right triangles, special triangles and trigonometry; include degree–radian conversion.\n- **Week 2, days 1–2:** circles: standard form, completing the square, arcs, sectors, inscribed angles.\n- **Days 3–4:** area and volume, including scaling questions.\n- **Days 5–7:** mixed timed sets of eight geometry questions in about 10 minutes; redo every miss from a fresh sketch."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (29, 'rich_text', 'Level-Specific Priorities', '{"markdown":"**Math section under about 500:** learn the reference sheet, triangle angle sums, the Pythagorean theorem and basic area. These appear early in modules.\n\n**About 500 to 650:** add similar triangles, special right triangles, SOH-CAH-TOA, and the circle equation with completing the square.\n\n**Above about 650:** practise combined problems: circles with tangents and right triangles, scaling of areas and volumes, and complementary-angle trig in unusual forms. These often sit at the end of the harder Module 2.\n\nThese ranges are Schood planning guides, not official bands."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (30, 'callout', 'Sketch Before You Calculate', '{"label":"Your scratch paper is a geometry tool","body":"Even when a figure is provided, redraw the essential part on scratch paper and write every given length and angle on it. Most geometry errors come from using the wrong segment or the wrong angle, and a labelled sketch makes those errors visible before you calculate anything."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (31, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Are figures drawn to scale?\nThe Bluebook directions say figures are drawn to scale unless a question says otherwise. You can use them to check whether an answer is reasonable.\n\n### Do I need to memorise volume formulas?\nNo. The reference sheet gives the volumes of a rectangular prism, cylinder, sphere, cone and pyramid. Do memorise the circle equation, arc length and sector area, which are not on it.\n\n### Will I need the unit circle?\nThe core skills are right-triangle trigonometry and radian–degree conversion. Know sin, cos and tan for 30°, 45° and 60° from the special right triangles, and the relationship sin x = cos(90° − x).\n\n### Can Desmos help with geometry?\nYes for circle equations, intersections of lines and circles, and trig calculations (in the right mode). Most angle and similar-triangle reasoning is faster on paper.\n\n### How many geometry questions are there?\nAbout 5 to 7 across the whole Math section, according to College Board''s specifications."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (32, 'rich_text', 'Related Practice', '{"markdown":"- [Geometry and trigonometry question bank](https://practice.sat.schood.online/bank?section_type=math&domain=geometry_trig): filter by difficulty.\n- [Hard geometry questions](https://practice.sat.schood.online/bank?section_type=math&domain=geometry_trig&difficulty=hard): circle and combined-figure problems.\n- [Today''s practice session](https://practice.sat.schood.online/today): mixed daily practice.\n- [SAT Simulator](https://sat.schood.online): geometry in a full timed test."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (33, 'rich_text', 'Next Steps', '{"markdown":"1. Learn circle graphing and trig mode checks in [Desmos and Calculator Strategy](https://playbook.sat.schood.online/desmos-and-calculator-strategy).\n2. Strengthen [Algebra](https://playbook.sat.schood.online/math-algebra) and [Advanced Math](https://playbook.sat.schood.online/math-advanced-math), which carry most of the Math section.\n3. Review data skills in [Problem-Solving and Data Analysis](https://playbook.sat.schood.online/math-problem-solving-data-analysis).\n4. Put it together with [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:math-geometry-trigonometry')::uuid
on conflict do nothing;

