-- Module 11: desmos-and-calculator-strategy (28 sections, 3449 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:desmos-and-calculator-strategy')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'desmos-and-calculator-strategy', 'desmos-and-calculator-strategy', 'Desmos and Calculator Strategy', 'Step-by-step Desmos techniques for the digital SAT: graphing both sides, systems and intersections, zeros and vertices, counting solutions, inequalities, tables and regressions, sliders, lists and statistics, plus when a pencil is faster.', 'published', 'public', 'en', 11, 'Desmos on the Digital SAT: Step-by-Step Calculator Strategy | SAT Playbook', 'Use the Bluebook Desmos calculator to solve SAT systems, quadratics, inequalities, regressions and parameter questions faster, with worked examples, decision rules and a drill.', array['SAT', 'Desmos', 'SAT calculator', 'Bluebook calculator', 'SAT Math strategy', 'graphing calculator', 'Digital SAT', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"desmos-and-calculator-strategy","module_group":"domain_math","migration_group":"math","hero_kicker":"Module 11","word_count":3449,"section_count":28,"reading_minutes":17,"estimated_reading_minutes":17,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Algebra question bank","url":"https://practice.sat.schood.online/bank?section_type=math&domain=algebra"},{"label":"Advanced Math question bank","url":"https://practice.sat.schood.online/bank?section_type=math&domain=advanced_math"},{"label":"Data analysis question bank","url":"https://practice.sat.schood.online/bank?section_type=math&domain=problem_solving_data_analysis"},{"label":"Full SAT simulator","url":"https://sat.schood.online"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:desmos-and-calculator-strategy:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why This Module Matters', '{"markdown":"On the digital SAT, a calculator is allowed on **every Math question**, and Bluebook includes an embedded **Desmos calculator** with a graphing mode and a scientific mode. That changes the test. Questions that once demanded several lines of algebra, such as finding where a line meets a parabola or counting the solutions of a system, can be answered by typing two expressions and clicking a point.\n\nMost students use only a fraction of what Desmos can do. They type numbers into it as if it were a basic calculator and never graph anything. This module teaches the techniques that matter on the SAT, step by step, with original worked examples, and it is just as clear about when Desmos is the slower option.\n\n**The goal is not to use Desmos on everything. It is to know, within a few seconds, whether Desmos or a pencil is faster for the question in front of you.**"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What You Will Be Able to Do', '{"items":["Open, resize and move the Bluebook calculator and switch between graphing and scientific modes.","Solve an equation by graphing each side and reading the intersection.","Solve systems of equations, including line and parabola or line and circle.","Find zeros, vertices, maxima and minima by clicking points of interest.","Count the number of solutions of a system or an equation.","Graph inequalities and test which points lie in a region.","Build a table and run linear, quadratic and exponential regressions.","Use sliders to answer \"for what value of k\" questions.","Compute mean, median and standard deviation from a list.","Recognise when solving by hand is faster and safer."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'The Calculator in Bluebook', '{"markdown":"College Board''s calculator policy describes the embedded Desmos calculator as having **graphing and scientific modes** that you can switch between at any point in the Math section. In Bluebook it opens in a panel that you can drag, and it is available for both Math modules. The reference sheet sits beside it.\n\nKey facts:\n\n- **You may also bring your own approved handheld calculator.** Graphing and scientific calculators without computer algebra system (CAS) features are allowed. If your handheld fails, you can continue with Desmos.\n- **No calculator on Reading and Writing.** A handheld must stay under your desk during that section.\n- **Mode switching does not carry content over.** Work typed in the scientific calculator does not appear in the graphing calculator, and the reverse. Check which mode you are in before typing.\n- **Practise in Bluebook itself.** Use Test Preview or a full-length practice test, or the Desmos test-practice calculators, so the layout is familiar. We could not inspect every setting of the Bluebook configuration, so confirm each technique in this module works in Test Preview before you rely on it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'callout', 'Calculator Habits Before Test Day', '{"label":"Rehearse, do not improvise","body":"A technique you have used fifty times is fast under pressure; one you read about last night is not. Pick the five techniques in this module that match your weakest question types, practise each in Bluebook Test Preview or a Bluebook practice test until the keystrokes are automatic, and decide in advance which calculator you will use. Switching tools on test day is a common source of lost minutes."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Typing Rules That Prevent Errors', '{"markdown":"Desmos reads what you type literally. Most calculator mistakes are typing mistakes.\n\n| Intention | Type | Common error |\n|---|---|---|\n| Two times x | `2x` | none, implicit multiplication works |\n| x squared | `x^2` | forgetting to press the right arrow after the exponent, so the next term ends up in the exponent |\n| (x + 1) over 3 | `(x+1)/3` | typing `x+1/3`, which means x plus one third |\n| e to the x | `e^x` | none |\n| Square root | `sqrt(x)` | the radical swallowing more than intended |\n| Subscripted variable | `x_1` | none; table columns use subscripts |\n| Absolute value | `abs(x)` or the pipe key | missing the closing bar |\n| Greater than or equal | `>=` | none; Desmos converts it to ≥ |\n\n**After typing any expression, look at how Desmos displays it.** The rendered version shows instantly whether a fraction, exponent or root covers the right part."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Technique 1: Graph Both Sides of an Equation', '{"markdown":"Any equation in one variable can be solved by graphing each side as its own function and finding where they meet.\n\n1. Type the left side as `y = ...`.\n2. Type the right side as `y = ...` in a new line.\n3. Click the point where the graphs cross. Desmos shows its coordinates.\n4. The **x-coordinate is the solution**. The y-coordinate is the common value of both sides.\n\n**Worked example.** Solve 3(x − 4) + 7 = 2x + 9.\n\nType `y = 3(x-4)+7` and `y = 2x+9`. The lines cross at (14, 37), so **x = 14**. Check: 3(10) + 7 = 37 and 2(14) + 9 = 37.\n\nBy hand this is also quick: 3x − 5 = 2x + 9, so x = 14. For a simple linear equation the pencil is just as fast. The technique earns its keep on equations that are awkward by hand, such as ones mixing exponents, roots or absolute values."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Technique 2: Solve a System by Intersection', '{"markdown":"1. Type each equation exactly as given. Desmos graphs equations in standard form, such as `4x+3y=25`, without rearranging.\n2. Click the intersection point.\n3. Read the coordinates, then **answer the question asked**, which is often a combination such as x + y.\n\n**Worked example.** 4x + 3y = 25 and 2x − y = 5. What is the value of x + y?\n\nThe lines meet at (4, 3), so **x + y = 7**.\n\n**Distractors you would see:** 4 (only x), 3 (only y), and 12 (x times y). Each comes from stopping one step early or reading the wrong request. The calculator found the point; you still have to read the question."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Technique 3: Zeros, Vertex, Maximum and Minimum', '{"markdown":"When you graph a function, Desmos marks special points in grey when you click on the curve: **x-intercepts (zeros), the y-intercept, and turning points (maxima and minima)**. Click a grey point to see its coordinates.\n\n**Worked example.** f(x) = 2x² − 12x + 10. What is the minimum value of f?\n\nType `f(x) = 2x^2-12x+10`. Click the curve. The zeros appear at (1, 0) and (5, 0), and the vertex at (3, −8). The **minimum value is −8**, reached at x = 3.\n\n**Traps:** the question asks for the minimum value (the y-coordinate, −8), not where it happens (x = 3). A distractor of 3 is common. Another is 10, the y-intercept, which some students mistake for the vertex."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Technique 4: Counting Solutions', '{"markdown":"\"How many solutions\" questions are some of the fastest Desmos wins. Graph both equations and count intersection points.\n\n**Worked example.** How many solutions does the system y = x² − 4x + 1 and y = 2x − 8 have?\n\nGraph both. The line touches the parabola at exactly one point, (3, −2). The system has **exactly one solution**.\n\nBy hand, setting the expressions equal gives x² − 6x + 9 = 0, which is (x − 3)² = 0: one repeated root, confirming the graph.\n\n**Zoom in when graphs look close.** A line that seems to touch a curve might actually miss it or cross it twice. Zoom on the area until the picture is unambiguous, or confirm with the discriminant."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Technique 5: Line and Circle Intersections', '{"markdown":"Desmos graphs circles typed in standard form directly.\n\n**Worked example.** At which points does the line y = x + 1 intersect the circle x² + y² = 25?\n\nType `x^2+y^2=25` and `y=x+1`. Click the two intersections: **(3, 4) and (−4, −3)**. Check: 9 + 16 = 25 and 16 + 9 = 25.\n\nThis is far faster than substituting and solving the resulting quadratic by hand, and it removes sign errors."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Technique 6: Inequalities and Regions', '{"markdown":"Type an inequality and Desmos shades the solution region. A dashed boundary means the boundary is not included (> or <); a solid boundary means it is included (≥ or ≤).\n\n**Worked example.** Which point satisfies both y > 2x − 3 and y ≤ −x + 6?\n\nA) (4, 6)  B) (0, −4)  C) (1, 2)  D) (5, 0)\n\nGraph both inequalities; the overlap is shaded twice. Then type the four points as `(4,6)`, `(0,-4)`, `(1,2)`, `(5,0)` and see which lies in the overlap. **The answer is C.**\n\n| Point | y > 2x − 3? | y ≤ −x + 6? |\n|---|---|---|\n| (4, 6) | 6 > 5, yes | 6 ≤ 2, no |\n| (0, −4) | −4 > −3, no | −4 ≤ 6, yes |\n| (1, 2) | 2 > −1, yes | 2 ≤ 5, yes |\n| (5, 0) | 0 > 7, no | 0 ≤ 1, yes |\n\n**Tip:** testing points by substitution, as in the table, is just as fast. Use whichever you trust more."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Technique 7: Tables', '{"markdown":"Tables let you enter data or check values of a function.\n\n1. Click the **+** button at the top of the expression list and choose **table**.\n2. The columns are named `x_1` and `y_1` by default. Type values into the cells.\n3. Desmos plots the points automatically.\n\nYou can also make a table **from a function**: type the function first, then use the option to create a table from it (in many versions, a table icon or menu next to the expression). Enter x-values and Desmos fills in the outputs. This is a quick way to check a function''s values against a table given in a question."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Technique 8: Linear Regression', '{"markdown":"When a question gives data and asks for a line of best fit or a prediction, use regression.\n\n1. Make a table with your data in `x_1` and `y_1`.\n2. In a new line, type `y_1 ~ m x_1 + b` (the tilde ~ means \"fit\").\n3. Desmos reports values for m and b and the correlation statistics.\n\n**Worked example.** A table shows x = 1, 2, 3, 4, 5 with y = 3.1, 4.9, 7.2, 8.8, 11.0. Using a linear model, which is closest to the predicted value of y when x = 8?\n\nA) 11.0  B) 14.9  C) 16.9  D) 24.8\n\nThe regression gives m ≈ 1.97 and b ≈ 1.09, with r ≈ 0.999. The prediction is 1.97(8) + 1.09 ≈ 16.85, so **C**.\n\n**Distractors:** 11.0 repeats the last data value, 14.9 adds only two steps of the slope to the last data point (x = 5 to x = 8 is three steps), and 24.8 multiplies the first y-value by 8.\n\nMost SAT line-of-best-fit questions give you the line already; regression is for the cases where you must find or compare a model yourself."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Technique 9: Quadratic and Exponential Regression', '{"markdown":"The same method works for other model shapes.\n\n- **Quadratic:** `y_1 ~ a x_1^2 + b x_1 + c`\n- **Exponential:** `y_1 ~ a b^(x_1)` (type `b^`, then `x_1`, then the right arrow)\n\n**Worked example.** A population is 200 at time 0, 260 at time 1, 338 at time 2 and 439.4 at time 3. What is the growth rate per time period?\n\nRun `y_1 ~ a b^(x_1)`. Desmos returns a = 200 and b = 1.3. The population is multiplied by 1.3 each period, a **growth rate of 30%**.\n\n**Trap:** b = 1.3 is the growth factor; the rate is b − 1 = 0.3. Choices showing 1.3% or 130% target exactly that confusion."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Technique 10: Sliders for "For What Value of k" Questions', '{"markdown":"When a constant is unknown, type it as a letter. Desmos offers to **add a slider**. Drag the slider and watch the graph change.\n\n**Worked example.** For what value of k does the system 3x + ky = 7 and 6x + 8y = 10 have no solution?\n\n1. Type `3x+ky=7` and accept the slider for k. Type `6x+8y=10`.\n2. Drag k until the two lines are parallel and do not meet. That happens at **k = 4**.\n3. Confirm by reasoning: with k = 4 the first equation is 3x + 4y = 7, and the second, divided by 2, is 3x + 4y = 5. Same left side, different right side: parallel lines, no solution.\n\n**Why confirm by algebra?** A slider moves in steps and the answer might not land exactly on a step. Use the slider to find the neighbourhood, then use the coefficient rule to get the exact value. Set the slider''s step to a smaller value if you need more precision."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Technique 11: Restricting a Domain', '{"markdown":"Braces after an expression restrict where it is drawn.\n\n- `y = x^2 {x >= 0}` draws only the right half of the parabola.\n- `y = 3x + 2 {0 <= x <= 5}` draws a segment.\n\nThis is useful for piecewise functions or for contexts where only some inputs make sense, such as time or quantities that cannot be negative."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Technique 12: Lists and Statistics', '{"markdown":"Desmos accepts lists in square brackets and has built-in statistics functions.\n\n1. Type `L = [12, 15, 15, 18, 20, 22, 45]`.\n2. Type `mean(L)`, `median(L)`, `stdev(L)` or `total(L)`.\n\n**Worked example.** For the data 12, 15, 15, 18, 20, 22, 45, what happens to the mean and median if 45 is removed?\n\nWith 45: mean 21, median 18. Without it: mean 17, median 16.5. **The mean falls by 4; the median falls by 1.5.** Outliers move the mean much more than the median.\n\n**Standard deviation note:** `stdev` gives the sample standard deviation and `stdevp` the population standard deviation. SAT questions on standard deviation are almost always conceptual (which set is more spread out?) rather than asking for a computed value, so you rarely need either."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Technique 13: Checking Equivalent Expressions', '{"markdown":"To test whether two expressions are equivalent, graph both. **If the graphs coincide everywhere, they are equivalent.** If they separate anywhere, they are not.\n\n**Worked example.** Is (x + 3)² − 9 equivalent to x² + 6x?\n\nGraph `y=(x+3)^2-9` and `y=x^2+6x`. The curves lie exactly on top of each other: **yes**. Expanding confirms: x² + 6x + 9 − 9 = x² + 6x.\n\nTo compare answer choices quickly, graph the original expression and then each choice in turn, or type each choice as a new line and toggle them on and off."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Technique 14: Degrees, Radians and the Scientific Mode', '{"markdown":"Trigonometry questions can be in degrees or radians. **Desmos evaluates trig functions in the current angle mode**, which you change in the graphing calculator''s settings (the wrench icon). The scientific mode also has an angle setting.\n\n- Before any trig calculation, check the mode.\n- Test it: sin(30) should be 0.5 in degree mode. If you get about −0.988, you are in radians.\n\nThe scientific mode is handy for long arithmetic and exact order of operations, but remember it does not share content with the graphing mode."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'When Not to Use Desmos', '{"markdown":"Desmos is slower when the work is mostly reading or reasoning.\n\n| Question type | Faster tool | Why |\n|---|---|---|\n| One-step or two-step linear equation | Head or pencil | Typing takes longer than solving |\n| Percent and ratio word problems | Pencil, quick arithmetic | Setup is the hard part, not computation |\n| Interpreting slope or intercept in a context | Reading | No calculation needed |\n| Geometry with angles and similar triangles | Sketch and reasoning | Desmos does not draw the figure for you |\n| Systems, intersections, number of solutions | Desmos | Visual answer in seconds |\n| Quadratic zeros, vertex, max and min | Desmos | Click the grey points |\n| Data with a requested model or prediction | Desmos regression | Exact parameters |\n| Parameter questions (\"value of k\") | Desmos slider plus algebra check | See the behaviour, confirm exactly |\n| Equivalent expression choices | Desmos graphs | Coinciding graphs settle it |\n\n**A useful rule:** if you can see the solution path and it is short, use the pencil. If the path involves solving a quadratic, a system, or an awkward equation, reach for Desmos."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Common Calculator Traps', '{"markdown":"- **Answering with the wrong coordinate.** The question asks for y, x + y or a maximum value; the intersection gives a point.\n- **Reading an approximate value as exact.** Desmos shows decimals; a choice may be the exact form, such as a fraction or a root. Compare carefully.\n- **Fraction typing errors.** `1/2x` and `1/(2x)` are different. Check the rendered expression.\n- **Wrong angle mode** on trig questions.\n- **Missing a second intersection** that lies off the visible screen. Zoom out before concluding there is only one.\n- **Slider too coarse.** A slider stepping by 1 can skip the exact value.\n- **Typing in the wrong mode** after switching between scientific and graphing."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Timing With Desmos', '{"markdown":"Desmos saves time only if the moves are automatic. In practice, aim for:\n\n- **Under 30 seconds** to type two equations and read an intersection.\n- **Under 45 seconds** to set up a table and run a regression with five data points.\n- **Under 20 seconds** to find a vertex or zeros by clicking.\n\nIf you are slower than this, practise the keystrokes until they are habits. Typing speed matters most in the last third of each Math module, where questions are hardest and time is tightest."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'A Weekly Desmos Routine', '{"markdown":"- **Two sessions of 15 minutes** a week for three weeks, practising one technique per session: intersections, zeros and vertex, regression, sliders, lists.\n- **During every Math practice set,** decide before solving whether the question is a pencil question or a Desmos question, and note whether you were right.\n- **Once a week,** redo three questions you solved by hand using Desmos, and three you solved with Desmos by hand. You will learn which method is faster for you.\n- **Take at least one full practice test in Bluebook** so the calculator panel and its placement are familiar."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Drill: Desmos Techniques', '{"markdown":"Use Desmos for each. Answers follow in the next section.\n\n1. Solve 5x − 7 = 3x + 11.\n2. The system y = 3x − 2 and x + 2y = 17 has solution (x, y). What is y?\n3. What is the maximum value of g(x) = −x² + 8x − 7?\n4. How many distinct real solutions does x³ − 3x² + 4 = 0 have?\n5. A quantity is 50 at x = 0, 72 at x = 2 and 103.68 at x = 4, and it grows exponentially. By what percent does it grow per unit increase in x?\n6. For the data 8, 11, 11, 14, 16, what is the mean minus the median?\n7. For what value of k does the system 2x + 5y = 9 and 6x + ky = 27 have infinitely many solutions?\n8. The graphs of y = |x − 2| and y = 0.5x + 1 intersect at two points. What is the sum of their x-coordinates? (Student-produced response.)"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Drill Answers and Explanations', '{"markdown":"1. **x = 9.** Graph `y=5x-7` and `y=3x+11`; they meet at (9, 38). By hand: 2x = 18.\n2. **y = 7.** The intersection is (3, 7). Check: 3(3) − 2 = 7 and 3 + 2(7) = 17. Choosing 3 means you reported x.\n3. **9.** The vertex is (4, 9). The value 4 is where the maximum occurs, not the maximum itself.\n4. **2.** The graph crosses the x-axis at x = −1 and touches it at x = 2 without crossing. Factored, the polynomial is (x + 1)(x − 2)², so x = 2 is a repeated root. Answering 3 counts the repeated root twice.\n5. **20%.** An exponential regression `y_1 ~ a b^(x_1)` gives a = 50 and b = 1.2, a growth factor of 1.2, or 20% per unit. Note that 72 is 50 times 1.44, which is the factor for two units, not one.\n6. **1.** `mean([8,11,11,14,16])` is 12 and `median` is 11.\n7. **k = 15.** Multiplying the first equation by 3 gives 6x + 15y = 27, identical to the second when k = 15. A slider shows the lines merge at k = 15.\n8. **20/3** (also accepted as 6.666 or 6.667). The intersections are at x = 6 (where x − 2 = 0.5x + 1) and x = 2/3 (where 2 − x = 0.5x + 1). Their sum is 20/3. Entering 6.67 would not be accepted, because a decimal that does not fit must use all available places: 6.666 or 6.667."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Frequently Asked Questions', '{"markdown":"### Should I bring my own calculator or use Desmos?\nUse whichever you have practised with most. Many students find Desmos faster for graphing questions; others like a familiar handheld for arithmetic. You may bring an approved handheld and still use Desmos.\n\n### Is Desmos the same in Bluebook as on the Desmos website?\nThe core graphing features are the same kind of tool, but test configurations can differ from the full website. Practise in Bluebook Test Preview or a Bluebook practice test, and use the Desmos test-practice page, to see the version you will meet.\n\n### Can Desmos solve word problems?\nNo. It computes and graphs. You still translate the words into expressions, and you still read what the question asks for.\n\n### Does using Desmos cost time on easy questions?\nOften yes. For short linear equations and percent problems, mental math or a pencil is faster.\n\n### What if Desmos shows a long decimal?\nCompare it with the answer choices, which may be in exact form. For student-produced responses, follow the entry rules: enter a fraction, or a decimal that fills the available places."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Related Practice', '{"markdown":"- [Algebra question bank](https://practice.sat.schood.online/bank?section_type=math&domain=algebra): systems and inequalities for Techniques 2, 6 and 10.\n- [Advanced Math question bank](https://practice.sat.schood.online/bank?section_type=math&domain=advanced_math): quadratics, exponentials and solution counting for Techniques 3, 4 and 9.\n- [Data analysis question bank](https://practice.sat.schood.online/bank?section_type=math&domain=problem_solving_data_analysis): regressions and statistics for Techniques 8 and 12.\n- [Today''s practice session](https://practice.sat.schood.online/today) and the [SAT Simulator](https://sat.schood.online) for timed practice."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Next Steps', '{"markdown":"1. Apply these techniques to the content in [Algebra](https://playbook.sat.schood.online/math-algebra) and [Advanced Math](https://playbook.sat.schood.online/math-advanced-math).\n2. Use regressions and lists with [Problem-Solving and Data Analysis](https://playbook.sat.schood.online/math-problem-solving-data-analysis).\n3. Check angle modes and circles with [Geometry and Trigonometry](https://playbook.sat.schood.online/math-geometry-trigonometry).\n4. Build Desmos into your timing plan with [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:desmos-and-calculator-strategy')::uuid
on conflict do nothing;

insert into public.sat_playbook_page_sources (page_id, source_id, sort_order, citation_note, is_primary)
select p.id, src.id, v.sort_order, v.citation_note, v.is_primary
from (values
  ('https://satsuite.collegeboard.org/sat/what-to-bring-do/calculator-policy', 1, 'Primary source for the embedded Desmos calculator and the handheld calculator policy', true),
  ('https://bluebook.collegeboard.org/students/tools', 2, 'Bluebook''s draggable Desmos calculator and reference sheet', false),
  ('https://satsuite.collegeboard.org/media/pdf/english-sat-test-directions-bb.pdf', 3, 'Math directions: calculator permitted for all questions', false),
  ('https://www.desmos.com/practice', 4, 'Desmos test-practice calculators', false),
  ('https://satsuite.collegeboard.org/sat/whats-on-the-test/math/overview', 5, 'Math domains and question types', false),
  ('https://satsuite.collegeboard.org/practice/practice-tests', 6, 'Official full-length practice in Bluebook', false)
) as v(url, sort_order, citation_note, is_primary)
join public.sat_playbook_sources src on src.url = v.url
join public.sat_playbook_pages p on p.id = md5('schood-sat-pb-page:desmos-and-calculator-strategy')::uuid
on conflict do nothing;

